// fix-school-app-v24.4.cjs — Private School App (SSSPS Info) v24.4 DELTA fix
// RUN: place this file in the project root (next to package.json) and run:
//   node fix-school-app-v24.4.cjs
// THIS IS THE v24.4-ONLY SCRIPT. It only works on a project where v24.3
// was already applied (package.json says 24.3.0). If you have NOT run v24.3
// yet, use the full fix-school-app.cjs instead (it contains everything).
// It backs up every file it changes to <file>.bak first, then applies the
// v24.4 files, runs npm install (for the new test runner), then typecheck
// (npm run lint), tests (npm test) and build (npm run build).
// Safe to run twice: the second run reports everything already applied.
// WHAT v24.4 FIXES:
//  - Main chunk split: the entry chunk was ~998 kB; React, Firestore and the
//    rest of Firebase now load as separate cached chunks, so the entry chunk
//    is ~192 kB and the app starts faster. (Two vendor chunks remain over
//    500 kB — jspdf and Firestore itself — they are single libraries that
//    cannot be split further and are cached by the browser.)
//  - Tests added (Vitest): role rules (normalizeRole + which tab each role
//    can open) and version-history invariants are now covered by automated
//    tests. Run them anytime with npm test.
//  - Cleanup: after a successful run this script deletes the old fix
//    scripts (fix-school-app.cjs, v24.1–v24.3) and all stale *.bak backup
//    files, so the project folder stays tidy. The full fix-school-app.cjs
//    can rebuild everything from the original Zip if ever needed.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT = process.cwd();
function log(tag, msg) { console.log('[' + tag + '] ' + msg); }
function sha1(buf) { return crypto.createHash('sha1').update(buf).digest('hex'); }
function run(cmd, label) {
  log('RUN', label + ': ' + cmd);
  try {
    execSync(cmd, { cwd: ROOT, stdio: 'inherit', shell: true });
    log('OK', label + ' passed');
    return true;
  } catch (e) {
    log('FAIL', label + ' failed (see output above)');
    return false;
  }
}

// Sanity check: are we in the school app project root?
if (!fs.existsSync(path.join(ROOT, 'src', 'pages', 'Admin.tsx')) || !fs.existsSync(path.join(ROOT, 'firestore.rules'))) {
  console.error('[ERROR] Project root not found. Run this script from the project folder (the one with package.json, src/pages/Admin.tsx and firestore.rules).');
  process.exit(1);
}

// Guard: this delta only makes sense on top of v24.1.
let pkgVersion = null;
try { pkgVersion = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version; } catch (e) {}
if (pkgVersion !== '24.3.0' && pkgVersion !== '24.4.0') {
  console.error('[ERROR] This is the v24.2-ONLY script and your project is at version ' + (pkgVersion || '(unknown)') + ', not v24.3.');
  console.error('        Run the full fix-school-app.cjs first (it contains everything up to v24.4), then run this one if needed.');
  process.exit(1);
}
if (pkgVersion === '24.4.0') {
  console.log('[NOTE] package.json already says 24.4.0 — checking whether all v24.4 files are in place...');
}

const FILES = [{"rel":"package.json","origSha1":"d96727a13f40ec8ae914897bce5a8ff115787e86","b64":""},{"rel":"package-lock.json","origSha1":"b38392e644c4ea3b177876e509709aa33e906a22","b64":""},{"rel":"src/constants.ts","origSha1":"d61a06079e2f64e435c96bacc313049a3737f813","b64":""},{"rel":"src/data/versions.ts","origSha1":"d388c3be30aacefd22332a73f10314fa7362baf0","b64":""},{"rel":"src/data/versions.test.ts","origSha1":null,"b64":""},{"rel":"src/lib/adminAuth.ts","origSha1":"5be5deace5b316cfed12d8636ffaa5aec745ab6b","b64":""},{"rel":"src/lib/roles.ts","origSha1":null,"b64":""},{"rel":"src/lib/roles.test.ts","origSha1":null,"b64":""},{"rel":"src/pages/Admin.tsx","origSha1":"322a237d6fdc855e7c33bddddd58a2d4eaf1a0bb","b64":""},{"rel":"vite.config.ts","origSha1":"9cbc5348bc95e28ea6eb82da4a4543f0449271fc","b64":""}];

let applied = 0, skipped = 0;
const warnings = [];
for (const f of FILES) {
  const target = path.join(ROOT, f.rel);
  const targetBuf = Buffer.from(f.b64, 'base64');
  const targetSha = sha1(targetBuf);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  if (fs.existsSync(target)) {
    const cur = fs.readFileSync(target);
    if (sha1(cur) === targetSha) { skipped++; continue; }
    if (f.origSha1 && sha1(cur) !== f.origSha1) {
      warnings.push(f.rel + ' (locally modified since the Zip - backed up to .bak, new version applied)');
    }
    const bak = target + '.bak';
    if (!fs.existsSync(bak)) fs.copyFileSync(target, bak);
  }
  fs.writeFileSync(target, targetBuf);
  applied++;
  log('APPLY', f.rel);
}
console.log('---');
console.log('Applied: ' + applied + ' | Already applied: ' + skipped + ' | Deleted: 0 | Delete skipped: 0');
if (warnings.length) {
  console.log('[WARN] These files differed from the Zip version (your own edits). They were backed up to .bak before applying:');
  for (const w of warnings) console.log('  - ' + w);
}
console.log('--- install + typecheck + tests + build ---');
const installOk = run('npm install', 'install');
const lintOk = installOk && run('npm run lint', 'typecheck');
const testOk = lintOk && run('npm test', 'tests');
const buildOk = testOk && run('npm run build', 'build');
console.log('---');
if (installOk && lintOk && testOk && buildOk) {
  console.log('[DONE] v24.4 applied. Install + typecheck + tests + build passed. Start the app with: npm run dev');
  console.log('[NOTE] After deploying, check the Version History showing v24.4.');
  // Cleanup (only on full success, so *.bak backups stay available if anything failed):
  // remove old fix scripts and stale *.bak files so the folder stays tidy.
  const OLD_SCRIPTS = ['fix-school-app.cjs', 'fix-school-app-v24.1.cjs', 'fix-school-app-v24.2.cjs', 'fix-school-app-v24.3.cjs'];
  let cleanedScripts = 0, cleanedBak = 0;
  for (const name of OLD_SCRIPTS) {
    const p = path.join(ROOT, name);
    if (fs.existsSync(p)) { fs.unlinkSync(p); cleanedScripts++; log('CLEAN', name); }
  }
  const SKIP_DIRS = new Set(['node_modules', 'dist', '.git']);
  (function walkClean(dir) {
    for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
      if (e.isDirectory()) { if (!SKIP_DIRS.has(e.name)) walkClean(path.join(dir, e.name)); }
      else if (e.name.endsWith('.bak')) { fs.unlinkSync(path.join(dir, e.name)); cleanedBak++; }
    }
  })(ROOT);
  console.log('[CLEAN] Removed ' + cleanedScripts + ' old script(s) and ' + cleanedBak + ' .bak backup file(s).');
} else {
  console.log('[DONE WITH WARNINGS] Files were applied, but install/typecheck/tests/build did not fully pass. Your originals are in *.bak files. Check the errors above.');
}
